#!/usr/bin/env python3
"""Prepares the Android project generated by `flutter create` for GoalPulse. Safe to run repeatedly.

  * INTERNET and POST_NOTIFICATIONS permissions
  * core-library desugaring (required by flutter_local_notifications)
  * minSdk 23
  * --cleartext  also allows plain http:// (local development only, never for a release)

Usage (from the mobile/ folder):  python3 tool/patch_android.py [--cleartext]
"""
import pathlib
import re
import sys

args = sys.argv[1:]
if '--root' in args:  # android/app directory override (used by the tests)
    root = pathlib.Path(args[args.index('--root') + 1])
else:
    root = pathlib.Path(__file__).resolve().parent.parent / 'android' / 'app'
DESUGAR = 'com.android.tools:desugar_jdk_libs:2.1.4'

# ── manifest ──────────────────────────────────────────────────
manifest = root / 'src' / 'main' / 'AndroidManifest.xml'
xml = manifest.read_text()
for perm in ('android.permission.INTERNET', 'android.permission.POST_NOTIFICATIONS'):
    if perm not in xml:
        xml = xml.replace('<application', f'<uses-permission android:name="{perm}"/>\n    <application', 1)
if '--cleartext' in args and 'usesCleartextTraffic' not in xml:
    xml = xml.replace('<application', '<application android:usesCleartextTraffic="true"', 1)
manifest.write_text(xml)

# ── gradle (Kotlin DSL or Groovy) ─────────────────────────────
kts, groovy = root / 'build.gradle.kts', root / 'build.gradle'
if kts.exists():
    path, flag, dep, min_old, min_new = kts, 'isCoreLibraryDesugaringEnabled = true', f'coreLibraryDesugaring("{DESUGAR}")', 'minSdk = flutter.minSdkVersion', 'minSdk = 23'
elif groovy.exists():
    path, flag, dep, min_old, min_new = groovy, 'coreLibraryDesugaringEnabled true', f"coreLibraryDesugaring '{DESUGAR}'", 'minSdkVersion flutter.minSdkVersion', 'minSdkVersion 23'
else:
    sys.exit('No android/app/build.gradle(.kts) found. Run `flutter create` first.')

g = path.read_text()
if 'oreLibraryDesugaringEnabled' not in g:
    g, n = re.subn(r'compileOptions\s*\{', 'compileOptions {\n        ' + flag, g, count=1)
    if n != 1:
        sys.exit('compileOptions block not found in ' + path.name)
if 'desugar_jdk_libs' not in g:
    if re.search(r'^dependencies\s*\{', g, re.M):
        g = re.sub(r'^dependencies\s*\{', 'dependencies {\n    ' + dep, g, count=1, flags=re.M)
    else:
        g += '\ndependencies {\n    ' + dep + '\n}\n'
g = g.replace(min_old, min_new)
path.write_text(g)
print(f'Patched {manifest.relative_to(root.parent.parent)} and {path.relative_to(root.parent.parent)}')
